export function createNativeScreenTree() {
  const tree=typeof structuredClone === 'function' ? structuredClone(NATIVE_SCREEN_TREE) : JSON.parse(JSON.stringify(NATIVE_SCREEN_TREE));
  const visit=node=>{const id=node.attrs?.['data-admin-weapon-editor'],overview=node.attrs?.['data-loadout-overview-weapon'];if(id&&WEAPON_SPECS[id]){const title=node.children?.find(child=>child.type==='strong');if(title)title.children=[{type:'#text',text:WEAPON_SPECS[id].name}];}if(overview)node.children=[{type:'#text',text:WEAPON_SPECS[overview.endsWith('primary')?'assault':'pistol'].name}];for(const child of node.children||[])visit(child);};visit(tree);return tree;
}
export const NATIVE_SCREEN_IDS = Object.freeze(['entryScreen','rotateGate','menu','lobbyScreen','pause','loadoutPanel','settingsPanel','adminPanel','lobbyQuitConfirm','mapDeleteConfirm','connectionOverlay','chatComposer','gameTextEditor']);
export default createNativeScreenTree;
